const r = await tools.exec_command({"cmd":"python - <<'PY'
import pandas as pd, numpy as np
from scipy.stats import chi2
D=pd.read_csv('/app/dataset/synthetic_stroke_data.csv')
valid=D.age.le(120)&D.bmi.between(10,60)&D.avg_glucose_level.between(20,800)
V=D.loc[valid].copy()
sets={}
for transform in ['raw','log2']:
 T=V[['age','bmi','avg_glucose_level']].copy()
 if transform=='log2': T['avg_glucose_level']=np.log2(T.avg_glucose_level)
 maxes=T.max()
 risk=(T/maxes).prod(axis=1)
 for proxy in [False,True]:
  X=T.copy()
  if proxy:X['risk_proxy']=risk
  mu=X.mean().to_numpy(); cov=X.cov().to_numpy(); inv=np.linalg.inv(cov)
  delta=X.to_numpy()-mu
  d2=np.einsum('ij,jk,ik->i',delta,inv,delta)
  for dfmode in ['ncols','3']:
   df=X.shape[1] if dfmode=='ncols' else 3
   crit=chi2.ppf(.99,df)
   inds=X.index[d2>crit].tolist()
   key=f'{transform}_proxy{proxy}_df{dfmode}'
   sets[key]=set(inds)
   print(key,'crit',crit,'count',len(inds),'indices',inds)
   order=np.argsort(-d2)[:20]
  print('  top20',[(int(X.index[i]),round(float(d2[i]),2)) for i in order])

print('\nPairwise symmetric diffs relevant')
keys=list(sets)
for a in keys:
 for b in keys:
  if a<b and len(sets[a]^sets[b])<40:
   print(a,b,'diff',len(sets[a]^sets[b]),sorted(sets[a]^sets[b]))

print('\nRaw vs log risk value descriptions')
for transform in ['raw','log2']:
 T=V[['age','bmi','avg_glucose_level']].copy()
 if transform=='log2':T.avg_glucose_level=np.log2(T.avg_glucose_level)
 print(transform,(T/T.max()).prod(axis=1).describe().to_string())
PY","workdir":"/app","yield_time_ms":10000,"max_output_tokens":30000});
